SELECT ast01_class_tree_id
  FROM ast01_class_tree
 WHERE ast01_company_id     = #{companyId}
   AND ast01_parent_tree_id = #{parentId}
   AND ast01_class_tree_nm  = #{assetName}
   AND ast01_asset_type     = '2'
 LIMIT 1

SELECT ast01_class_tree_id
  FROM ast01_class_tree
 WHERE ast01_company_id     = #{companyId}
   AND ast01_parent_tree_id = #{parentId}
   AND ast01_isin           = #{itemCode}
   AND ast01_asset_type     = '2'
 LIMIT 1

SELECT COALESCE(MAX(ast01_seq),0) + 1
  FROM ast01_class_tree
 WHERE ast01_company_id     = #{companyId}
   AND ast01_parent_tree_id = #{parentId}

